package cli

import (
	"bytes"
	"compress/gzip"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/spf13/cobra"
)

// TestHistoryIndexReusesScanCache verifies v6 content-authorized reuse,
// including files whose mtime changes without a content change.
func TestHistoryIndexReusesScanCache(t *testing.T) {
	repoDir := t.TempDir()
	env := semanticTestEnv(t, repoDir)
	runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot("1.0"))
	now := time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC)
	storage, err := repoStoragePaths((&cobra.Command{}).Context(), runner, env, repoDir)
	if err != nil {
		t.Fatalf("storage: %v", err)
	}
	sessionDir := filepath.Join(storage.BrainDir, exportSessionsDirectory, "main")
	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
		t.Fatalf("mkdir session dir: %v", err)
	}
	sessionPath := filepath.Join(sessionDir, "session.jsonl")
	line := `{"type":"agent_message","message":"Decision: keep the export cursor authoritative for transcript reuse."}` + "\n"
	if err := os.WriteFile(sessionPath, []byte(line), 0o600); err != nil {
		t.Fatalf("write session: %v", err)
	}

	source, err := writeBrainHistoryIndexAndSource(storage.BrainDir, now, nil)
	if err != nil {
		t.Fatalf("first build: %v", err)
	}
	if source.Decisions != 1 {
		t.Fatalf("expected 1 decision, got %+v", source)
	}

	cachePath := filepath.Join(storage.BrainDir, filepath.FromSlash(historyScanCachePath))
	cache := loadHistoryScanCache(storage.BrainDir)
	if len(cache.Files) != 1 {
		t.Fatalf("expected 1 cached file, got %d (%s)", len(cache.Files), cachePath)
	}

	// Replace the cached records for the (unchanged) file with a sentinel. If
	// the second build reuses the cache, the sentinel propagates into the index;
	// if it re-scanned the file, it would not.
	for key, entry := range cache.Files {
		entry.Records = []historyRecord{{
			ID:      "sentinel",
			Kind:    "decision",
			Path:    key,
			Line:    1,
			Summary: "Decision: sentinel cache marker.",
		}}
		cache.Files[key] = entry
	}
	saveHistoryScanCache(storage.BrainDir, cache)

	var lastDone, lastTotal int
	progress := func(done, total int) { lastDone, lastTotal = done, total }
	if _, _, err := buildBrainHistoryIndex(storage.BrainDir, now, progress); err != nil {
		t.Fatalf("second build: %v", err)
	}
	if lastTotal != 1 || lastDone != 1 {
		t.Fatalf("progress = %d/%d, want 1/1", lastDone, lastTotal)
	}
	reused := loadHistoryScanCache(storage.BrainDir)
	if !cacheContainsRecordID(reused, "sentinel") {
		t.Fatalf("second build did not reuse cache: %+v", reused.Files)
	}

	// An mtime-only change still has the same authoritative digest and must
	// preserve cached records.
	mtimeOnly := now.Add(30 * time.Minute)
	if err := os.Chtimes(sessionPath, mtimeOnly, mtimeOnly); err != nil {
		t.Fatalf("mtime-only change: %v", err)
	}
	if _, _, err := buildBrainHistoryIndex(storage.BrainDir, now, nil); err != nil {
		t.Fatalf("mtime-only build: %v", err)
	}
	mtimeReused := loadHistoryScanCache(storage.BrainDir)
	if !cacheContainsRecordID(mtimeReused, "sentinel") {
		t.Fatalf("mtime-only change invalidated content cache: %+v", mtimeReused.Files)
	}

	// Changing the content (size + mtime) must invalidate the entry and re-scan.
	if err := os.WriteFile(sessionPath, []byte(line+line), 0o600); err != nil {
		t.Fatalf("rewrite session: %v", err)
	}
	future := now.Add(time.Hour)
	if err := os.Chtimes(sessionPath, future, future); err != nil {
		t.Fatalf("chtimes: %v", err)
	}
	if _, _, err := buildBrainHistoryIndex(storage.BrainDir, now, nil); err != nil {
		t.Fatalf("third build: %v", err)
	}
	rescanned := loadHistoryScanCache(storage.BrainDir)
	if cacheContainsRecordID(rescanned, "sentinel") {
		t.Fatalf("changed file was not re-scanned: stale sentinel survived: %+v", rescanned.Files)
	}
}

func TestHistoryScanCacheRejectsSameSizeSameMtimeReplacement(t *testing.T) {
	brainDir := t.TempDir()
	rel := "sessions/main/session.jsonl"
	path := filepath.Join(brainDir, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		t.Fatal(err)
	}
	oldLine := `{"type":"agent_message","message":"Decision: retain old searchable token."}` + "\n"
	newLine := `{"type":"agent_message","message":"Decision: retain new searchable token."}` + "\n"
	if len(oldLine) != len(newLine) {
		t.Fatal("cache replacement fixture must preserve byte length")
	}
	if err := os.WriteFile(path, []byte(oldLine), 0o600); err != nil {
		t.Fatal(err)
	}
	manifest := exportManifest{SchemaVersion: brainManifestSchemaVersion, Sources: &brainSources{Sessions: &sessionSourceManifest{
		DefaultBranch: "main", Sessions: []exportSession{{SessionID: "s1", Branch: "main", TranscriptPath: rel}},
	}}}
	if err := writeBrainManifestAndReadme(brainDir, manifest); err != nil {
		t.Fatal(err)
	}
	if _, _, err := buildBrainHistoryIndex(brainDir, time.Now().UTC(), nil); err != nil {
		t.Fatal(err)
	}
	oldInfo, err := os.Stat(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(path); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(newLine), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.Chtimes(path, oldInfo.ModTime(), oldInfo.ModTime()); err != nil {
		t.Fatal(err)
	}
	newInfo, err := os.Stat(path)
	if err != nil {
		t.Fatal(err)
	}
	if newInfo.Size() != oldInfo.Size() || !newInfo.ModTime().Equal(oldInfo.ModTime()) {
		t.Fatal("replacement did not preserve cache-visible metadata")
	}
	index, _, err := buildBrainHistoryIndex(brainDir, time.Now().UTC(), nil)
	if err != nil {
		t.Fatal(err)
	}
	joined := ""
	for _, record := range index.Records {
		joined += record.Summary + "\n"
